import random
from sc2 import run_game, maps, Race, Difficulty
from sc2.player import Bot, Computer
from sc2.constants import *
from sc2.bot_ai import BotAI

class ThreeBaseThreeStargateBot(BotAI):
    async def on_step(self, iteration):
        await self.distribute_workers()

        # Chrono boost active nexuses
        for nexus in self.townhalls.ready:
            if nexus.energy >= 50:
                abilities = await self.get_available_abilities(nexus)
                if AbilityId.EFFECT_CHRONOBOOSTENERGYCOST in abilities:
                    targets = [nexus] + self.structures.of_type({UnitTypeId.GATEWAY, UnitTypeId.CYBERNETICSCORE, UnitTypeId.STARGATE}).ready
                    if targets:
                        target = random.choice(targets)
                        await self.do(nexus(AbilityId.EFFECT_CHRONOBOOSTENERGYCOST, target))

        # If no nexuses left, attack with all workers
        if not self.townhalls:
            for worker in self.workers.idle:
                await self.do(worker.attack(self.enemy_start_locations[0]))
            for worker in self.workers:
                if worker.is_collecting or worker.is_idle:
                    await self.do(worker.attack(self.enemy_start_locations[0]))
            return

        # Build pylons when supply is low
        if self.supply_left < 5 and self.already_pending(UnitTypeId.PYLON) == 0:
            nexuses = self.townhalls.ready
            if nexuses.exists and self.can_afford(UnitTypeId.PYLON):
                pos = nexuses.random.position.towards(self.game_info.map_center, 5)
                await self.build(UnitTypeId.PYLON, near=pos)

        # Train probes on undersaturated nexuses
        for nexus in self.townhalls.ready.idle:
            if self.can_afford(UnitTypeId.PROBE) and nexus.assigned_harvesters < nexus.ideal_harvesters:
                await self.do(nexus.train(UnitTypeId.PROBE))

        # Expand if less than 3 nexuses
        if self.townhalls.amount + self.already_pending(UnitTypeId.NEXUS) < 3 and self.can_afford(UnitTypeId.NEXUS):
            await self.expand_now()

        # Build gateway if none exists
        if self.structures(UnitTypeId.GATEWAY).amount + self.already_pending(UnitTypeId.GATEWAY) < 1:
            if self.structures(UnitTypeId.PYLON).ready.exists and self.can_afford(UnitTypeId.GATEWAY):
                pylon = self.structures(UnitTypeId.PYLON).ready.random
                await self.build(UnitTypeId.GATEWAY, near=pylon)

        # Build cybernetics core if gateway is ready and no core exists
        if self.structures(UnitTypeId.GATEWAY).ready.exists and self.structures(UnitTypeId.CYBERNETICSCORE).amount + self.already_pending(UnitTypeId.CYBERNETICSCORE) < 1:
            if self.can_afford(UnitTypeId.CYBERNETICSCORE):
                pylon = self.structures(UnitTypeId.PYLON).ready.random
                await self.build(UnitTypeId.CYBERNETICSCORE, near=pylon)

        # Build assimilators near completed nexuses
        for nexus in self.townhalls.ready:
            vgs = self.vespene_geyser.closer_than(10, nexus)
            for vg in vgs:
                if self.can_afford(UnitTypeId.ASSIMILATOR) and not self.gas_buildings.closer_than(1, vg).exists and self.already_pending(UnitTypeId.ASSIMILATOR) < 2:
                    worker = self.select_build_worker(vg.position)
                    if worker:
                        await self.do(worker.build(UnitTypeId.ASSIMILATOR, vg))

        # Build stargates if less than 3 and at least 3 nexuses
        if self.townhalls.ready.amount >= 3:
            if self.structures(UnitTypeId.CYBERNETICSCORE).ready.exists:
                if self.structures(UnitTypeId.STARGATE).amount + self.already_pending(UnitTypeId.STARGATE) < 3:
                    if self.can_afford(UnitTypeId.STARGATE):
                        pylon = self.structures(UnitTypeId.PYLON).ready.random
                        await self.build(UnitTypeId.STARGATE, near=pylon)

        # Train void rays at idle stargates when at least 3 townhalls
        if self.townhalls.ready.amount >= 3:
            for stargate in self.structures(UnitTypeId.STARGATE).ready.idle:
                if self.can_afford(UnitTypeId.VOIDRAY):
                    await self.do(stargate.train(UnitTypeId.VOIDRAY))

        # Attack with void rays if more than 5
        voidrays = self.units(UnitTypeId.VOIDRAY).ready
        if voidrays.amount > 5:
            for vr in voidrays.idle:
                await self.do(vr.attack(self.enemy_start_locations[0]))

run_game(
    maps.get("(2)CatalystLE"),
    [Bot(Race.Protoss, ThreeBaseThreeStargateBot()), Computer(Race.Protoss, Difficulty.Easy)],
    realtime=False,
)
